UpdateContext(
    {
        varShowConfirmationDialog: false,
        varConfirmationDialogTitle: "",
        varConfirmationDialogSubtitle: ""
    }
);
UpdateContext({varRegistriesInConflict: ""});
Clear(colConflictRegistrie);
ForAll(
    Filter(
        'CH-Tbl-ClientDataChangeRequestLines',
        ChangeRequestID.'CH-Tbl-ClientDataChangeRequest' = gvarSelectedChangeRequest.'CH-Tbl-ClientDataChangeRequest'
    ) As CRL,
    With(
        {
            varConflictRow: LookUp(
                'CH-Tbl-ClientDataChangeRequestLines',
                'Field Definition'.LogicalName = CRL.'Field Definition'.LogicalName && (ChangeStatus = 'ChangeStatus (CH-Tbl-ClientDataChangeRequestLines)'.Submitted || ChangeStatus = 'ChangeStatus (CH-Tbl-ClientDataChangeRequestLines)'.Approved)
            )
        },
        Collect(
            colConflictRegistrie,
            varConflictRow
        )
    );

);
If(
    !IsEmpty(colConflictRegistrie),
    UpdateContext(
        {
            varRegistriesInConflict: "Existen cambios en status submitted/approved en conflicto con el RFC actual. Los siguientes campos se encuentran en conflicto: " & Concat(
                colConflictRegistrie,
                Concatenate(
                    'Field Definition'.Name,
                    " (",
                    ChangeRequestID.Name,
                    "|",
                    Name,
                    ")"
                ),
                ", "
            )
        }
    );
    Notify(
        varRegistriesInConflict,
        NotificationType.Error
    );
    ,
    UpdateContext(
        {
            varShowConfirmationDialog: true,
            varConfirmationDialogTitle: "Confirmar envio de RFC",
            varConfirmationDialogSubtitle: "Una vez enviado ya no podra editar este RFC, ¿Desea continuar?"
        }
    )
)

Table(
    {
        ItemKey: "new",
        ItemDisplayName: "New",
        ItemIconName: "Add",
        ItemVisible: IsBlank(DVFluentDetailsList1.Selected)
    },
    {
        ItemKey: "edit",
        ItemDisplayName: "Edit",
        ItemIconName: "Edit",
        ItemVisible: !IsBlank(DVFluentDetailsList1.Selected)
    },
    {
        ItemKey: "delete",
        ItemDisplayName: "Delete",
        ItemIconName: "Delete",
        ItemVisible: !IsBlank(DVFluentDetailsList1.Selected)
    },
    {
        ItemKey: "refresh",
        ItemDisplayName: "Refresh",
        ItemIconName: "Refresh"
    }
)

Switch(
    Self.SelectedButton.Label,
    "Cancel",
    UpdateContext(
        {
            varShowConfirmationDialog: false,
            varConfirmationDialogTitle: "",
            varConfirmationDialogSubtitle: ""
        }
    );
    ,
    "Ok",
    UpdateContext(
        {
            varScreenSpinnerLabel: "Guardando...",
            varScreenSpinnerVisibility: true
        }
    );
    Clear(colSubmittionErrors);
    UpdateContext(
        {
            varRegistriesInConflict: "",
            varContinue: true
        }
    );
    Clear(colConflictRegistrie);
    ClearCollect(
        colRegistriesToSubmit,
        Filter(
            'CH-Tbl-ClientDataChangeRequestLines',
            ChangeRequestID.'CH-Tbl-ClientDataChangeRequest' = gvarSelectedChangeRequest.'CH-Tbl-ClientDataChangeRequest'
        )
    );
    ForAll(
        Filter(
            'CH-Tbl-ClientDataChangeRequestLines',
            ChangeRequestID.'CH-Tbl-ClientDataChangeRequest' = gvarSelectedChangeRequest.'CH-Tbl-ClientDataChangeRequest'
        ) As CRL,
        With(
            {
                varConflictRow: LookUp(
                    'CH-Tbl-ClientDataChangeRequestLines',
                    'Field Definition'.LogicalName = CRL.'Field Definition'.LogicalName && (ChangeStatus = 'ChangeStatus (CH-Tbl-ClientDataChangeRequestLines)'.Submitted || ChangeStatus = 'ChangeStatus (CH-Tbl-ClientDataChangeRequestLines)'.Approved)
                )
            },
            Collect(
                colConflictRegistrie,
                varConflictRow
            )
        );
    );
    If(
        !IsEmpty(colConflictRegistrie),
        UpdateContext(
            {
                varRegistriesInConflict: "Existen cambios en status submitted/approved en conflicto con el RFC actual. Los siguientes campos se encuentran en conflicto: " & Concat(
                    colConflictRegistrie,
                    Concatenate(
                        'Field Definition'.Name,
                        " (",
                        ChangeRequestID.Name,
                        "-",
                        Name,
                        ")"
                    ),
                    ", "
                )
            }
        );
        Notify(
            varRegistriesInConflict,
            NotificationType.Error
        );
        UpdateContext({varContinue: false});
    );
    If(
        varContinue,
        ForAll(
            colRegistriesToSubmit As Row,
            Collect(
                colSubmittionErrors,
                Row
            );
            IfError(
                Patch(
                    'CH-Tbl-ClientDataChangeRequestLines',
                    Row,
                    {ChangeStatus: 'ChangeStatus (CH-Tbl-ClientDataChangeRequestLines)'.Submitted}
                );
                Remove(
                    colSubmittionErrors,
                    Row
                );
                ,
                Blank()
            )
        );
    );
    If(
        IsEmpty(colSubmittionErrors) && varContinue,
        Patch(
            'CH-Tbl-ClientDataChangeRequests',
            gvarSelectedChangeRequest,
            {ChangeStatus: 'ChangeStatus (CH-Tbl-ClientDataChangeRequests)'.Submited}
        );
        Notify(
            "RFC guardado y enviado",
            NotificationType.Success
        );
        UpdateContext(
            {
                varShowConfirmationDialog: false,
                varConfirmationDialogTitle: "",
                varConfirmationDialogSubtitle: ""
            }
        );
        Set(
            gvarSelectedChangeRequest,
            Blank()
        );
        Refresh('CH-Tbl-ClientDataChangeRequestLines');
        Refresh('CH-Tbl-ClientDataChangeRequests');
         If(
                IsBlank(FromScreen),
                Navigate('screen Clients', ScreenTransition.Fade),  // no hay historial → pantalla por defecto
                Back()                                        // hay historial → volver normalmente
            );,
        Notify(
            "Hubo problemas al guardar los registros, intentelo nuevamente",
            NotificationType.Error
        )
    );
    UpdateContext(
        {
            varShowConfirmationDialog: false,
            varConfirmationDialogTitle: "",
            varConfirmationDialogSubtitle: ""
        }
    );

);

